package com.chatmentions;

import net.runelite.api.ChatMessageType;

/**
 * The game's chat tabs, in the order its chatbox lists them, each with its label. All is the merged view of every kept
 * line, not a kind of line: {@link #of} never answers it. Pure: it reads a {@link ChatMessageType} and nothing else of
 * the client.
 */
enum Chat
{
	ALL("All"),
	GAME("Game"),
	PUBLIC("Public"),
	PRIVATE("Private"),
	CHANNEL("Channel"),
	CLAN("Clan"),
	TRADE("Trade");

	private final String label;

	Chat(String label)
	{
		this.label = label;
	}

	/** The tab's word: "All", "Game", "Public", "Private", "Channel", "Clan" or "Trade". */
	String label()
	{
		return label;
	}

	/**
	 * The chat a kind of line belongs to, or null for every kind the plugin does not keep (and for null). The guest clan
	 * and group ironman lines fold under {@link #CLAN} as the game folds them; the friends chat is {@link #CHANNEL}. Never
	 * {@link #ALL}.
	 */
	static Chat of(ChatMessageType type)
	{
		if (type == null)
		{
			return null;
		}
		switch (type)
		{
			case PUBLICCHAT:
			case MODCHAT:
			case AUTOTYPER:
			case MODAUTOTYPER:
				return PUBLIC;
			case PRIVATECHAT:
			case PRIVATECHATOUT:
			case MODPRIVATECHAT:
				return PRIVATE;
			case FRIENDSCHAT:
			case FRIENDSCHATNOTIFICATION:
				return CHANNEL;
			case CLAN_CHAT:
			case CLAN_MESSAGE:
			case CLAN_GUEST_CHAT:
			case CLAN_GUEST_MESSAGE:
			case CLAN_GIM_CHAT:
			case CLAN_GIM_MESSAGE:
				return CLAN;
			case GAMEMESSAGE:
			case ENGINE:
			case BROADCAST:
			case WELCOME:
			case LOGINLOGOUTNOTIFICATION:
			case FRIENDNOTIFICATION:
			case IGNORENOTIFICATION:
			case ITEM_EXAMINE:
			case NPC_EXAMINE:
			case OBJECT_EXAMINE:
			case SPAM:
			case PLAYERRELATED:
			case TENSECTIMEOUT:
			case LEVELUPMESSAGE:
			case CONSOLE:
			case DIDYOUKNOW:
			case CLAN_CREATION_INVITATION:
			case CLAN_GIM_FORM_GROUP:
			case CLAN_GIM_GROUP_WITH:
				return GAME;
			case TRADEREQ:
			case TRADE:
			case TRADE_SENT:
			case CHALREQ_TRADE:
			case CHALREQ_FRIENDSCHAT:
			case CHALREQ_CLANCHAT:
				return TRADE;
			default:
				return null;
		}
	}

	/**
	 * Whether a line is one a player typed: true for the ten chat kinds, false for the game's own broadcasts, for a
	 * private message the player sent, for every other kind and for null.
	 */
	static boolean spoken(ChatMessageType type)
	{
		if (type == null)
		{
			return false;
		}
		switch (type)
		{
			case CLAN_CHAT:
			case CLAN_GUEST_CHAT:
			case CLAN_GIM_CHAT:
			case FRIENDSCHAT:
			case PRIVATECHAT:
			case MODPRIVATECHAT:
			case PUBLICCHAT:
			case MODCHAT:
			case AUTOTYPER:
			case MODAUTOTYPER:
				return true;
			default:
				return false;
		}
	}
}

package com.chatmentions;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/**
 * The kept lines of one chat, oldest first, up to a capacity; the oldest goes when more arrive. Every method is
 * synchronized on the buffer, because a line arrives on the client thread and the panel reads on the event thread.
 *
 * <p>Choice: the lines are an {@link ArrayDeque}; the numbers held are always contiguous (added one by one, dropped only
 * from the front). The numbers are never reset by {@link #clear} or {@link #resize}.
 */
final class ChatBuffer
{
	private final Deque<ChatLine> lines = new ArrayDeque<>();
	private int capacity;
	private long next = 1;

	/** A buffer of the capacity; below 1 reads as 1. */
	ChatBuffer(int capacity)
	{
		this.capacity = Math.max(1, capacity);
	}

	/** Keeps a line as the newest with the next number; the oldest goes when more than the capacity are held. */
	synchronized ChatLine add(Chat chat, long at, String who, String text, boolean spoken, int icon)
	{
		final ChatLine line = new ChatLine(chat, next++, at, who, text, spoken, icon);
		lines.addLast(line);
		trim();
		return line;
	}

	/** A copy of the lines, oldest first. */
	synchronized List<ChatLine> lines()
	{
		return new ArrayList<>(lines);
	}

	/** Sets the capacity (below 1 reads as 1) and drops the oldest lines beyond it. */
	synchronized void resize(int capacity)
	{
		this.capacity = Math.max(1, capacity);
		trim();
	}

	/** Drops every line; the numbers keep rising. */
	synchronized void clear()
	{
		lines.clear();
	}

	private void trim()
	{
		while (lines.size() > capacity)
		{
			lines.removeFirst();
		}
	}
}

package com.chatmentions;

/** One kept chat line: the chat it belongs to (never {@link Chat#ALL}), its sequence number, when it arrived, who sent it, its plain text, whether a player typed it and the index of the rank icon
 * in front of the sender's name (-1 for none). */
final class ChatLine
{
	private final Chat chat;
	private final long seq;
	private final long at;
	private final String who;
	private final String text;
	private final boolean spoken;
	private final int icon;

	ChatLine(Chat chat, long seq, long at, String who, String text, boolean spoken, int icon)
	{
		this.chat = chat;
		this.seq = seq;
		this.at = at;
		this.who = who == null ? "" : who;
		this.text = text == null ? "" : text;
		this.spoken = spoken;
		this.icon = icon;
	}

	/** The chat the line belongs to. */
	Chat chat()
	{
		return chat;
	}

	/** The line's number in its buffer. */
	long seq()
	{
		return seq;
	}

	/** When the line arrived, in milliseconds since the epoch. */
	long at()
	{
		return at;
	}

	/** The sender's name; empty when there is none. */
	String who()
	{
		return who;
	}

	/** The line's plain text. */
	String text()
	{
		return text;
	}

	/** Whether a player typed the line. */
	boolean spoken()
	{
		return spoken;
	}

	/** The index of the sender's rank icon, -1 for none. */
	int icon()
	{
		return icon;
	}
}

package com.chatmentions;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
