	/**
	 * The column of cards: as wide as the scroll pane's view, so a card wraps its line and the horizontal bar stays away
	 * (the model's {@code HistoryList.getScrollableTracksViewportWidth}). A change of its width asks for a layout again,
	 * since the cards' heights follow it.
	 */
	private static final class CardColumn extends JPanel implements Scrollable
	{
		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return SCROLL_STEP;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(SCROLL_STEP, visibleRect.height - SCROLL_STEP);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}

		@Override
		public void setBounds(int x, int y, int width, int height)
		{
			final boolean widthChanges = width != getWidth();
			super.setBounds(x, y, width, height);
			if (widthChanges)
			{
				revalidate();
			}
		}
	}

	/**
	 * A card's line: non-editable, non-focusable, see-through, wrapping to the card's width, which it reads off the
	 * column (the card's own width is not yet set when the column asks for its height).
	 */
	private static final class CardText extends JTextPane
	{
		private final JPanel column;
		/** The width the height was measured for, and the size it gave; the document never changes after the card is made. */
		private int measuredFor = -1;
		private Dimension measured;

		CardText(JPanel column)
		{
			this.column = column;
			setEditable(false);
			setFocusable(false);
			setOpaque(false);
			setBorder(null);
			setCaret(new StillCaret());
			setHighlighter(null);
			setAlignmentX(Component.LEFT_ALIGNMENT);
		}

		/** The height the text takes wrapped at the card's inner width, once the column has a width. */
		@Override
		public Dimension getPreferredSize()
		{
			final Container card = getParent();
			final int width = card == null ? 0 : column.getWidth() - card.getInsets().left - card.getInsets().right;
			if (width <= 0)
			{
				return super.getPreferredSize();
			}
			if (width != measuredFor || measured == null)
			{
				final View root = getUI().getRootView(this);
				root.setSize(width, Integer.MAX_VALUE);
				measured = new Dimension(width, (int) Math.ceil(root.getPreferredSpan(View.Y_AXIS)));
				measuredFor = width;
			}
			return new Dimension(measured);
		}
	}

	/**
	 * The how-to's wrapped words: a 12 px white HTML label whose text carries a body width, set by {@link #fit} from the
	 * card's inner width less its indent, so the browser-style layout wraps the words to the card.
	 *
	 * <p>Choice: a width that changes by less than 1 px does nothing; before the first fit the label holds the plain words.
	 */
	private static final class WrapLabel extends JLabel
	{
		private final int indent;
		private final String words;
		private int fitted = -1;

		WrapLabel(int indent, String words)
		{
			super(words);
			this.indent = indent;
			this.words = words;
			setFont(FontManager.getDefaultFont().deriveFont(12f));
			setForeground(Color.WHITE);
			setVerticalAlignment(SwingConstants.TOP);
			setAlignmentX(Component.LEFT_ALIGNMENT);
		}

		/** Sets the label's text for a card whose inner width is {@code width}; the same width sets nothing again. */
		void fit(int width)
		{
			final int room = width - indent;
			if (room <= 0 || room == fitted)
			{
				return;
			}
			fitted = room;
			// Swing's HTML renderer scales a width given in px by 96/72 (its px are 1.3 of its points); a width in
			// pt is taken as the pixels asked for, so the lines fold inside the card.
			setText("<html><body style='width:" + room + "pt'>" + escape(words) + "</body></html>");
		}

		private static String escape(String text)
		{
			return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
		}
	}

	/** A caret that never scrolls its text: the kept chat's view stays where a card click put it. */
	private static final class StillCaret extends DefaultCaret
	{
		StillCaret()
		{
			setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
		}

		@Override
		protected void adjustVisibility(Rectangle nloc)
		{
			// Never scrolls.
		}
	}

	/** A left-aligned flow that wraps to further lines and asks for the height they take (the tab row, the chips). */
	private static final class WrapLayout extends FlowLayout
	{
		WrapLayout(int gap)
		{
			super(FlowLayout.LEFT, gap, gap);
		}

		@Override
		public Dimension preferredLayoutSize(Container target)
		{
			return wrapped(target, true);
		}

		@Override
		public Dimension minimumLayoutSize(Container target)
		{
			return wrapped(target, false);
		}

		/** The size of the parts set in lines no wider than the room the row has (its parent's width once laid out). */
		private Dimension wrapped(Container target, boolean preferred)
		{
			synchronized (target.getTreeLock())
			{
				final Container parent = target.getParent();
				int room = parent != null && parent.getWidth() > 0
					? parent.getWidth() - parent.getInsets().left - parent.getInsets().right : target.getWidth();
				if (room <= 0)
				{
					room = Integer.MAX_VALUE;
				}
				final Insets insets = target.getInsets();
				final int most = room == Integer.MAX_VALUE ? room
					: room - insets.left - insets.right - 2 * getHgap();
				int width = 0;
				int height = 0;
				int lineWidth = 0;
				int lineHeight = 0;
				for (final Component part : target.getComponents())
				{
					if (!part.isVisible())
					{
						continue;
					}
					final Dimension size = preferred ? part.getPreferredSize() : part.getMinimumSize();
					if (lineWidth > 0 && lineWidth + getHgap() + size.width > most)
					{
						width = Math.max(width, lineWidth);
						height += lineHeight + getVgap();
						lineWidth = 0;
						lineHeight = 0;
					}
					lineWidth += (lineWidth > 0 ? getHgap() : 0) + size.width;
					lineHeight = Math.max(lineHeight, size.height);
				}
				width = Math.max(width, lineWidth);
				height += lineHeight;
				return new Dimension(width + insets.left + insets.right + 2 * getHgap(),
					height + insets.top + insets.bottom + 2 * getVgap());
			}
		}
	}

	/**
	 * One chat tab: its word in the default face at 11 px, the lit one in the brand orange with a 2 px bar of the same
	 * orange under the word, the others grey (white under the mouse). It paints itself whatever look and feel is on and
	 * takes no keyboard.
	 */
	private static final class TabButton extends JToggleButton
	{
		private static final int PAD_X = 2;
		private static final int PAD_TOP = 2;
		private static final int BAR_GAP = 1;
		private static final int BAR_HEIGHT = 2;
		private static final int PAD_BOTTOM = 2;

		private boolean under;

		TabButton(String words)
		{
			super(words);
			setFont(FontManager.getDefaultFont().deriveFont(11f));
			setFocusable(false);
			setOpaque(false);
			setContentAreaFilled(false);
			setBorderPainted(false);
			setFocusPainted(false);
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseEntered(MouseEvent e)
				{
					under = true;
					repaint();
				}

				@Override
				public void mouseExited(MouseEvent e)
				{
					under = false;
					repaint();
				}
			});
		}

		/** The word with its padding, the bar and the room under it. */
		@Override
		public Dimension getPreferredSize()
		{
			final FontMetrics metrics = getFontMetrics(getFont());
			return new Dimension(metrics.stringWidth(getText()) + 2 * PAD_X,
				PAD_TOP + metrics.getHeight() + BAR_GAP + BAR_HEIGHT + PAD_BOTTOM);
		}

		/** The whole tab: its word and, when lit, the bar under it. */
		@Override
		protected void paintComponent(Graphics g)
		{
			final boolean on = isSelected();
			g.setFont(getFont());
			g.setColor(on ? ColorScheme.BRAND_ORANGE : under ? Color.WHITE : ColorScheme.LIGHT_GRAY_COLOR);
			final FontMetrics metrics = g.getFontMetrics();
			g.drawString(getText(), PAD_X, PAD_TOP + metrics.getAscent());
			if (on)
			{
				g.fillRect(PAD_X, PAD_TOP + metrics.getHeight() + BAR_GAP, getWidth() - 2 * PAD_X, BAR_HEIGHT);
			}
		}
	}

	/** A text field that paints its hint in grey where the words would start, while it is empty and has no focus. */
	private static final class HintField extends JTextField
	{
		@Override
		protected void paintComponent(Graphics g)
		{
			super.paintComponent(g);
			if (getText().isEmpty() && !hasFocus())
			{
				g.setFont(getFont());
				g.setColor(FAINT_GREY);
				final FontMetrics metrics = g.getFontMetrics();
				g.drawString(HINT_TEXT, getInsets().left, (getHeight() - metrics.getHeight()) / 2 + metrics.getAscent());
			}
		}
	}
}

package com.chatmentions;

import com.google.inject.Provides;
import java.awt.Color;
import java.awt.GraphicsConfiguration;
import java.awt.GraphicsDevice;
import java.awt.GraphicsEnvironment;
import java.awt.Insets;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Toolkit;
import java.awt.Window;
import java.awt.datatransfer.StringSelection;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * 2h Chat Mentions: keeps every line of the watched chats and makes a card of each mention, with the fourteen settings
 * working in RuneLite's config panel and in the sidebar's menu, and shows the cards over the kept chat in the sidebar.
 */
@PluginDescriptor(
	name = "2h Chat Mentions",
	internalName = "chat-mentions",
	description = "The chat lines that name you or your keywords, as cards over the kept chat, so you catch up after being away. (v" + Version.CURRENT + ")",
	tags = {"chat", "clan", "mentions", "keywords", "afk", "history"}
)
public class ChatMentionsPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(ChatMentionsPlugin.class);

	/** The sidebar button's place. */
	private static final int NAV_PRIORITY = 7;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Client client;

	@Inject
	private ChatMentionsConfig config;

	@Inject
	private ColorPickerManager colorPickerManager;

	private NavigationButton navButton;
	private volatile MentionFeed feed;
	private volatile ChatMentionsPanel panel;
	private volatile boolean nameWanted;
	private final RankIcons icons = new RankIcons();

	@Provides
	ChatMentionsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ChatMentionsConfig.class);
	}

	@Override
	protected void startUp()
	{
		feed = new MentionFeed(config.linesKept(), config.cardsKept());
		applySettings();
		nameWanted = true;
		final PanelSettings settings = new PanelSettings()
		{
			@Override
			public String keywords()
			{
				return config.keywords();
			}

			@Override
			public void setKeywords(String words)
			{
				write("keywords", words);
			}

			@Override
			public boolean wholeWordsOnly()
			{
				return config.wholeWordsOnly();
			}

			@Override
			public void setWholeWordsOnly(boolean on)
			{
				write("wholeWordsOnly", on);
			}

			@Override
			public boolean watched(Chat chat)
			{
				return ChatMentionsPlugin.this.watched(chat);
			}

			@Override
			public void setWatched(Chat chat, boolean on)
			{
				final String key = watchKey(chat);
				if (key != null)
				{
					write(key, on);
				}
			}

			@Override
			public int cardsKept()
			{
				return config.cardsKept();
			}

			@Override
			public void setCardsKept(int n)
			{
				write("cardsKept", n);
			}

			@Override
			public int linesKept()
			{
				return config.linesKept();
			}

			@Override
			public void setLinesKept(int n)
			{
				write("linesKept", n);
			}

			@Override
			public Color keywordColour()
			{
				return config.defaultKeywordColour();
			}

			@Override
			public void setKeywordColour(Color colour)
			{
				write("defaultKeywordColour", colour);
			}

			@Override
			public String keywordColours()
			{
				return config.keywordColours();
			}

			@Override
			public void setKeywordColours(String setting)
			{
				write("keywordColours", setting);
			}

			@Override
			public int cardsShare()
			{
				return config.cardsShare();
			}

			@Override
			public void setCardsShare(int percent)
			{
				write("cardsShare", percent);
			}

			@Override
			public String shownTab()
			{
				return config.shownTab();
			}

			@Override
			public void setShownTab(String name)
			{
				write("shownTab", name);
			}

			private void write(String key, Object value)
			{
				configManager.setConfiguration(ChatMentionsConfig.GROUP, key, value);
			}
		};
		panel = new ChatMentionsPanel(this::resetToDefault, settings, (parent, title, current, onChange, onClose, at) ->
		{
			final Window owner = SwingUtilities.windowForComponent(parent);
			final RuneliteColorPicker colourPicker = colorPickerManager.create(owner, current, title, true);
			colourPicker.setOnColorChange(onChange);
			colourPicker.setOnClose(onClose);
			// Owned by the client's window, the picker inherits its always-on-top state, so it never pins itself.
			colourPicker.setLocation(ScreenPlace.near(at, colourPicker.getSize(), screenOf(at)));
			colourPicker.setVisible(true);
		}, feed, icons, ChatMentionsPlugin::copyToClipboard);
		navButton = NavigationButton.builder()
			.tooltip("2h Chat Mentions")
			.icon(NavIcon.create())
			.priority(NAV_PRIORITY)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		log.info("2h Chat Mentions {} started on RuneLite {}", Version.CURRENT, RuneLiteProperties.getVersion());
	}

	@Override
	protected void shutDown()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		final MentionFeed old = feed;
		if (old != null)
		{
			old.clear();
		}
		feed = null;
		panel = null;
		nameWanted = false;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			nameWanted = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		final MentionFeed current = feed;
		if (!nameWanted || current == null)
		{
			return;
		}
		final Player player = client.getLocalPlayer();
		final String name = player == null ? null : player.getName();
		if (name != null && !name.isEmpty())
		{
			current.playerName(name);
			nameWanted = false;
			final ChatMentionsPanel named = panel;
			if (named != null)
			{
				SwingUtilities.invokeLater(named::settingsChanged);
			}
			log.debug("The player's name is known");
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final MentionFeed current = feed;
		if (current == null)
		{
			return;
		}
		icons.capture(RankIcons.indexIn(event.getName()), client.getModIcons());
		if (current.line(event.getType(), event.getName(), event.getMessage(), System.currentTimeMillis()))
		{
			log.debug("A mention card was made in the {} chat", Chat.of(event.getType()).label());
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ChatMentionsConfig.GROUP.equals(event.getGroup()) || feed == null)
		{
			return;
		}
		applySettings();
		final ChatMentionsPanel current = panel;
		if (current != null)
		{
			SwingUtilities.invokeLater(current::settingsChanged);
		}
	}

	/**
	 * The feed's partial flag for the whole-words setting: the inverse.
	 * Choice: package-private static so the plugin's own call is also what the test reads.
	 */
	static boolean partialOf(boolean wholeWordsOnly)
	{
		return !wholeWordsOnly;
	}

	/** Hands the config's values to the feed. */
	private void applySettings()
	{
		final MentionFeed current = feed;
		if (current == null)
		{
			return;
		}
		current.keywords(config.keywords(), partialOf(config.wholeWordsOnly()));
		for (final Chat chat : Chat.values())
		{
			current.watch(chat, watched(chat));
		}
		current.linesKept(config.linesKept());
		current.cardsKept(config.cardsKept());
	}

	private boolean watched(Chat chat)
	{
		switch (chat)
		{
			case GAME:
				return config.watchGame();
			case PUBLIC:
				return config.watchPublic();
			case PRIVATE:
				return config.watchPrivate();
			case CHANNEL:
				return config.watchChannel();
			case CLAN:
				return config.watchClan();
			case TRADE:
				return config.watchTrade();
			default:
				return true;
		}
	}

	/** The config key of a chat's switch; null for All, which has none and writes nothing. */
	private static String watchKey(Chat chat)
	{
		switch (chat)
		{
			case GAME:
				return "watchGame";
			case PUBLIC:
				return "watchPublic";
			case PRIVATE:
				return "watchPrivate";
			case CHANNEL:
				return "watchChannel";
			case CLAN:
				return "watchClan";
			case TRADE:
				return "watchTrade";
			default:
				return null;
		}
	}

	/**
	 * Puts the text on the system clipboard (the bundled Chat History's way); called on the event thread by a card's
	 * "Copy name".
	 */
	private static void copyToClipboard(String text)
	{
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
	}

	/** The usable area (the screen less its task bar and the like) of the screen {@code at} is on. */
	private static Rectangle screenOf(Point at)
	{
		final GraphicsEnvironment environment = GraphicsEnvironment.getLocalGraphicsEnvironment();
		GraphicsConfiguration found = environment.getDefaultScreenDevice().getDefaultConfiguration();
		for (final GraphicsDevice device : environment.getScreenDevices())
		{
			final GraphicsConfiguration candidate = device.getDefaultConfiguration();
			if (candidate.getBounds().contains(at))
			{
				found = candidate;
				break;
			}
		}
		final Rectangle bounds = found.getBounds();
		final Insets insets = Toolkit.getDefaultToolkit().getScreenInsets(found);
		return new Rectangle(bounds.x + insets.left, bounds.y + insets.top,
			bounds.width - insets.left - insets.right, bounds.height - insets.top - insets.bottom);
	}

	/** "Reset to default": unsets the fourteen keys. */
	private void resetToDefault()
	{
		final String[] keys = {"keywords", "wholeWordsOnly", "watchPublic", "watchPrivate", "watchChannel", "watchClan",
			"watchGame", "watchTrade", "cardsKept", "linesKept", "defaultKeywordColour",
			"keywordColours", "cardsShare", "shownTab"};
		for (final String key : keys)
		{
			configManager.unsetConfiguration(ChatMentionsConfig.GROUP, key);
		}
	}
}

package com.chatmentions;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;

/**
 * The 2hBuilds coin, the family mark every 2hBuilds plugin carries in the top-left corner of its sidebar icon: a
 * hammered gold disc 9 px across with its "2h" struck in dark brown, drawn in code so it needs no image file. It is
 * the coin half of {@link NavIcon}, pulled out so the one picture can be copied into another plugin's package
 * unchanged - it refers to nothing of this plugin's and to no class but the JDK's.
 *
 * <p>{@link #paint} draws it where it sits in a 16 x 16 icon, the disc centred on (4.5, 4.5): three jittered discs
 * with antialiasing on, then the two letters crisp on top, antialiasing off again, so a caller that draws more on
 * the same {@link Graphics2D} afterwards gets the hint it had not set itself.
 */
final class CoinGlyph
{
	private static final Color RIM = new Color(88, 62, 16);
	private static final Color EDGE = new Color(140, 102, 30);
	private static final Color FACE = new Color(196, 156, 58);
	private static final Color INK = new Color(52, 36, 8);

	/** The coin's centre and the three radii of its rim, edge and face. */
	private static final double COIN_X = 4.5, COIN_Y = 4.5;
	private static final double[] RADII = {4.7, 3.9, 3.3};
	private static final Color[] RINGS = {RIM, EDGE, FACE};
	/** The hammering: one offset per sixteenth of the edge. */
	private static final double[] JITTER = {0.3, -0.2, 0.4, 0.1, -0.3, 0.2, 0.4, -0.1, 0.2, -0.4, 0.3, 0.0, -0.3, 0.4, -0.1, 0.2};

	/** The letters, one character a pixel: "2" then "h", 3 wide and 5 tall each, a 1 px gap between. */
	private static final String[] TWO = {"###", "..#", "###", "#..", "###"};
	private static final String[] H = {"#..", "#..", "###", "#.#", "#.#"};
	private static final int LETTERS_X = 1, LETTERS_Y = 2;

	private CoinGlyph()
	{
	}

	/**
	 * Draws the coin in the top-left of the 16 x 16 icon {@code g} paints on: three jittered discs with
	 * antialiasing, then the letters crisp on top. Leaves the antialiasing hint off and the colour at the letters'
	 * ink.
	 */
	static void paint(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		for (int i = 0; i < RADII.length; i++)
		{
			g.setColor(RINGS[i]);
			g.fill(coin(RADII[i]));
		}
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		glyph(g, TWO, LETTERS_X, LETTERS_Y);
		glyph(g, H, LETTERS_X + 4, LETTERS_Y);
	}

	private static Path2D coin(double radius)
	{
		final Path2D path = new Path2D.Double();
		for (int i = 0; i < JITTER.length; i++)
		{
			final double angle = i * Math.PI * 2 / JITTER.length;
			final double r = radius + JITTER[i];
			final double x = COIN_X + Math.cos(angle) * r;
			final double y = COIN_Y + Math.sin(angle) * r;
			if (i == 0)
			{
				path.moveTo(x, y);
			}
			else
			{
				path.lineTo(x, y);
			}
		}
		path.closePath();
		return path;
	}

	private static void glyph(Graphics2D g, String[] rows, int x, int y)
	{
		g.setColor(INK);
		for (int r = 0; r < rows.length; r++)
		{
			for (int c = 0; c < rows[r].length(); c++)
			{
				if (rows[r].charAt(c) == '#')
				{
					g.fillRect(x + c, y + r, 1, 1);
				}
			}
		}
	}
}

package com.chatmentions;

import java.awt.Color;
import java.awt.Component;
import java.awt.Point;
import java.util.function.Consumer;

/**
 * What the sidebar panel needs of a colour picker: open one on a colour, hear each new colour, and hear it close. The
 * plugin backs it with RuneLite's own picker; a test backs it with a stub that keeps the callbacks, so the panel never
 * touches RuneLite's picker class.
 */
interface ColourPicker
{
	/**
	 * Opens the picker.
	 *
	 * @param parent the component the picker belongs to
	 * @param title the picker window's title
	 * @param current the colour the picker starts on
	 * @param onChange told each colour the picker settles on while it is open
	 * @param onClose told the colour the picker holds when it closes
	 * @param at the point on the screen the picker opens at: the mouse at the press
	 */
	void pick(Component parent, String title, Color current, Consumer<Color> onChange, Consumer<Color> onClose,
		Point at);
}

package com.chatmentions;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Line2D;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;

/**
 * The 2hBuilds settings icon, drawn in code: a ring with eight teeth and a hole through the middle, the picture the
 * settings icon of every 2hBuilds plugin shows (STANDARD A4). It is the bank's icon, pulled out of its widget helper so
 * the one picture can be copied into another plugin unchanged; it refers to no class of the plugin it sits in.
 *
 * <p>The ring is a stroke and not a filled disc, so the middle stays transparent and the picture reads as a settings
 * icon at 12 px rather than as a cogged blob. The teeth are eight round-capped spokes every 45 degrees, starting on
 * the ring's own circle so each is rooted in the ring's metal and none reaches into the hole. Every length is a
 * fraction of the size, so the same shape comes out at any size.
 */
final class GearGlyph
{
	/** The number of teeth. */
	static final int TEETH = 8;
	/** The smallest side drawn: below it the hole closes and the teeth merge. */
	static final int MIN_SIZE = 7;

	private GearGlyph()
	{
	}

	/**
	 * A new square icon, transparent except for the ring and its teeth.
	 *
	 * @param size   the icon's side in px; anything under {@value #MIN_SIZE} is raised to it
	 * @param colour the ink; null falls back to the sidebar's quiet grey, {@link ColorScheme#LIGHT_GRAY_COLOR}
	 */
	static ImageIcon icon(int size, Color colour)
	{
		final int s = Math.max(MIN_SIZE, size);
		final BufferedImage img = new BufferedImage(s, s, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
			g.setColor(colour == null ? ColorScheme.LIGHT_GRAY_COLOR : colour);
			final double centre = s / 2.0;
			// The ring's centre line, the width of its metal, and how far a tooth's centre line reaches - the last
			// one pulled in by half a tooth so the round cap lands inside the icon instead of being clipped.
			final double ring = centre * 0.52;
			final float ringWidth = (float) Math.max(1.5, s * 0.2);
			final float toothWidth = (float) Math.max(1.3, s * 0.16);
			final double toothOut = centre - toothWidth / 2.0 - 0.25;
			g.setStroke(new BasicStroke(ringWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.draw(new Ellipse2D.Double(centre - ring, centre - ring, ring * 2.0, ring * 2.0));
			g.setStroke(new BasicStroke(toothWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			for (int i = 0; i < TEETH; i++)
			{
				final double angle = i * 2.0 * Math.PI / TEETH;
				final double cos = Math.cos(angle);
				final double sin = Math.sin(angle);
				g.draw(new Line2D.Double(centre + cos * ring, centre + sin * ring,
					centre + cos * toothOut, centre + sin * toothOut));
			}
		}
		finally
		{
			g.dispose();
		}
		return new ImageIcon(img);
	}
}

package com.chatmentions;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The words that make a chat line a mention, and the finder that marks them in a line. Immutable.
 *
 * <p>Choice: a word is matched ignoring case; with {@code partial} off a hit must stand between characters that are not
 * letters or digits (or at an end of the text), with it on a hit may sit inside a word.
 */
final class Keywords
{
	private final List<String> words;
	private final boolean partial;

	private Keywords(List<String> words, boolean partial)
	{
		this.words = Collections.unmodifiableList(words);
		this.partial = partial;
	}

	/**
	 * The keywords of a comma-separated setting, led by the player's own name: the cleaned {@code name}, when it is not
	 * empty, is the first word; the setting's pieces follow in their order, each with U+00A0 as a space, trimmed, runs of
	 * spaces collapsed, empties dropped, and a piece equal to an earlier word or to the name ignoring case dropped; the
	 * rest is kept in order and case.
	 */
	static Keywords of(String setting, boolean partial, String name)
	{
		final List<String> kept = new ArrayList<>();
		if (name != null)
		{
			final String own = cleaned(name);
			if (!own.isEmpty())
			{
				kept.add(own);
			}
		}
		if (setting != null)
		{
			for (final String piece : setting.split(",", -1))
			{
				final String word = cleaned(piece);
				if (!word.isEmpty() && !has(kept, word))
				{
					kept.add(word);
				}
			}
		}
		return new Keywords(kept, partial);
	}

	private static String cleaned(String piece)
	{
		return piece.replace('\u00a0', ' ').trim().replaceAll(" +", " ");
	}

	private static boolean has(List<String> list, String word)
	{
		for (final String have : list)
		{
			if (have.equalsIgnoreCase(word))
			{
				return true;
			}
		}
		return false;
	}

	/** The words, in the setting's order; cannot be changed. */
	List<String> words()
	{
		return words;
	}

	/**
	 * The hits in the text as {@code {start, end, word}}, sorted by start, {@code word} being the index into
	 * {@link #words()} of the keyword that made the hit (the name is word 0); two that overlap are merged into one that
	 * keeps the word of the one that comes first in {@code words()}, two that only touch are left apart. U+00A0 reads as a space (one character for one, so the offsets are the text's own). A null or
	 * empty text, or no words, gives an empty list.
	 */
	List<int[]> find(String text)
	{
		final List<int[]> hits = new ArrayList<>();
		if (text == null || text.isEmpty() || words.isEmpty())
		{
			return hits;
		}
		final String read = text.replace('\u00a0', ' ');
		for (int which = 0; which < words.size(); which++)
		{
			final String word = words.get(which);
			final int length = word.length();
			for (int index = 0; index + length <= read.length(); index++)
			{
				if (!read.regionMatches(true, index, word, 0, length))
				{
					continue;
				}
				final int end = index + length;
				final boolean whole = (index == 0 || !Character.isLetterOrDigit(read.charAt(index - 1)))
					&& (end == read.length() || !Character.isLetterOrDigit(read.charAt(end)));
				if (partial || whole)
				{
					hits.add(new int[]{index, end, which});
				}
			}
		}
		Collections.sort(hits, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
		final List<int[]> merged = new ArrayList<>();
		for (final int[] hit : hits)
		{
			final int[] last = merged.isEmpty() ? null : merged.get(merged.size() - 1);
			if (last != null && hit[0] < last[1])
			{
				last[1] = Math.max(last[1], hit[1]);
				last[2] = Math.min(last[2], hit[2]);
			}
			else
			{
				merged.add(hit);
			}
		}
		return merged;
	}
}

package com.chatmentions;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** One card: a kept line that named a keyword, with the chat it came from and the spans to colour. */
final class Mention
{
	private final Chat chat;
	private final long seq;
	private final long at;
	private final String who;
	private final String text;
	private final List<int[]> spans;
	private final int icon;

	Mention(Chat chat, long seq, long at, String who, String text, List<int[]> spans, int icon)
	{
		this.chat = chat;
		this.seq = seq;
		this.at = at;
		this.who = who == null ? "" : who;
		this.text = text == null ? "" : text;
		this.spans = spans == null ? Collections.<int[]>emptyList() : Collections.unmodifiableList(new ArrayList<>(spans));
		this.icon = icon;
	}

	/** The chat the line came from. */
	Chat chat()
	{
		return chat;
	}

	/** The line's number in its chat's buffer. */
	long seq()
	{
		return seq;
	}

	/** When the line arrived, in milliseconds since the epoch. */
	long at()
	{
		return at;
	}

	/** The sender's name; empty when there is none. */
	String who()
	{
		return who;
	}

	/** The line's plain text. */
	String text()
	{
		return text;
	}

	/** The {@code {start, end}} spans of the keywords in the text; cannot be changed. */
	List<int[]> spans()
	{
		return spans;
	}

	/** The index of the sender's rank icon, -1 for none. */
	int icon()
	{
		return icon;
	}
}

package com.chatmentions;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import net.runelite.api.ChatMessageType;

/**
 * The wiring engine: every line of a watched chat goes into that chat's buffer and into the All buffer, and a spoken line from someone else
 * that holds a keyword also becomes a card in the ledger. It holds no RuneLite state but the message kind it is
 * handed.
 *
 * <p>Choice: every method is synchronized on the feed, so one line is handled at a time; the setters come from the
 * client thread or from start-up. The buffers and the ledger lock themselves, and the ledger tells its listeners with
 * its own lock let go, so a listener that only hands work to the event thread is fine with the feed's lock held.
 *
 * <p>Choice: the feed's own listeners are told with the feed's lock held, since a listener only hands work to the event
 * thread.
 */
final class MentionFeed
{
	private final Map<Chat, ChatBuffer> buffers = new EnumMap<>(Chat.class);
	private final MentionLedger ledger;
	private final Set<Chat> watched = EnumSet.allOf(Chat.class);
	private String setting = "";
	private boolean partial;
	private String playerName = "";
	private Keywords keywords;
	private final List<Consumer<Chat>> listeners = new ArrayList<>();

	MentionFeed(int linesKept, int cardsKept)
	{
		for (final Chat chat : Chat.values())
		{
			buffers.put(chat, new ChatBuffer(linesKept));
		}
		ledger = new MentionLedger(cardsKept);
		keywords = Keywords.of(setting, partial, playerName);
	}

	/** Remembers the keyword setting and the partial switch; the player's name is always the first keyword. */
	synchronized void keywords(String setting, boolean partial)
	{
		this.setting = setting;
		this.partial = partial;
		keywords = Keywords.of(setting, partial, playerName);
	}

	/** Keeps the player's own name (null reads as empty) and rebuilds the keywords. */
	synchronized void playerName(String rawName)
	{
		playerName = PlainText.name(rawName);
		keywords = Keywords.of(setting, partial, playerName);
	}

	/** The player's own cleaned name; empty while it is unknown. */
	synchronized String playerName()
	{
		return playerName;
	}

	/** Choice: All is always watched, so switching it off does nothing. */
	synchronized void watch(Chat chat, boolean on)
	{
		if (chat == Chat.ALL)
		{
			return;
		}
		if (on)
		{
			watched.add(chat);
		}
		else
		{
			watched.remove(chat);
		}
	}

	synchronized void linesKept(int n)
	{
		for (final ChatBuffer buffer : buffers.values())
		{
			buffer.resize(n);
		}
		tellEveryChat();
	}

	synchronized void cardsKept(int n)
	{
		ledger.resize(n);
	}

	/**
	 * Handles one chat line.
	 *
	 * @return whether the line made a card
	 */
	synchronized boolean line(ChatMessageType type, String rawName, String rawMessage, long now)
	{
		final Chat chat = Chat.of(type);
		if (chat == null || !watched.contains(chat))
		{
			return false;
		}
		String who = PlainText.name(rawName);
		if (type == ChatMessageType.PRIVATECHATOUT)
		{
			who = "To " + who;
		}
		final String text = PlainText.plain(rawMessage);
		final boolean spoken = Chat.spoken(type);
		final int icon = RankIcons.indexIn(rawName);
		final ChatLine line = buffers.get(chat).add(chat, now, who, text, spoken, icon);
		buffers.get(Chat.ALL).add(chat, now, who, text, spoken, icon);
		final boolean card = card(line);
		tell(chat);
		tell(Chat.ALL);
		return card;
	}

	/** Makes a card of a kept line when a player other than this one typed it and it holds a keyword. */
	private boolean card(ChatLine line)
	{
		if (!line.spoken() || (!playerName.isEmpty() && line.who().equalsIgnoreCase(playerName)))
		{
			return false;
		}
		final List<int[]> spans = keywords.find(line.text());
		if (spans.isEmpty())
		{
			return false;
		}
		ledger.add(new Mention(line.chat(), line.seq(), line.at(), line.who(), line.text(), spans, line.icon()));
		return true;
	}

	/**
	 * The keyword spans in a text, by the keywords in force now.
	 *
	 * <p>Choice: the kept chat colours its lines' keywords with the feed's own keywords, the player's name
	 * included, so the panel asks the feed rather than building keywords of its own.
	 */
	synchronized List<int[]> spans(String text)
	{
		return keywords.find(text);
	}

	/** Has {@code listener} told, with the chat, after each kept line, and with every chat after a clear or a resize. */
	synchronized void listen(Consumer<Chat> listener)
	{
		listeners.add(listener);
	}

	synchronized ChatBuffer buffer(Chat chat)
	{
		return buffers.get(chat);
	}

	synchronized MentionLedger ledger()
	{
		return ledger;
	}

	/** Empties every buffer and the ledger. */
	synchronized void clear()
	{
		for (final ChatBuffer buffer : buffers.values())
		{
			buffer.clear();
		}
		ledger.clear();
		tellEveryChat();
	}

	private void tell(Chat chat)
	{
		for (final Consumer<Chat> listener : listeners)
		{
			listener.accept(chat);
		}
	}

	private void tellEveryChat()
	{
		for (final Chat chat : Chat.values())
		{
			tell(chat);
		}
	}
}

package com.chatmentions;

import java.util.ArrayList;
import java.util.List;

/**
 * The cards, newest first, up to a cap. Shaped as the clan plugin's card history: the plugin adds a mention as it finds
 * one; the panel lists the entries and listens for a change.
 *
 * <p>Choice: every method is synchronized on the ledger itself, because a line arrives on the client thread and the
 * panel reads on the event thread; the listeners are told after the lock is let go, on the thread that changed the
 * ledger, so a listener never holds the lock while it works.
 */
final class MentionLedger
{
	private final List<Mention> entries = new ArrayList<>();
	private final List<Runnable> listeners = new ArrayList<>();
	private int cap;

	/** A ledger of the cap; below 1 reads as 1. */
	MentionLedger(int cap)
	{
		this.cap = Math.max(1, cap);
	}

	/** Keeps the mention as the newest; the oldest goes when more than the cap are held. Tells every listener. Null adds nothing. */
	void add(Mention mention)
	{
		if (mention == null)
		{
			return;
		}
		synchronized (this)
		{
			entries.add(0, mention);
			while (entries.size() > cap)
			{
				entries.remove(entries.size() - 1);
			}
		}
		changed();
	}

	/** A copy of the mentions, newest first. */
	synchronized List<Mention> mentions()
	{
		return new ArrayList<>(entries);
	}

	/** Removes that very object (identity) and tells; false, and silent, when it is null or not held. */
	boolean markRead(Mention mention)
	{
		if (mention == null)
		{
			return false;
		}
		synchronized (this)
		{
			int found = -1;
			for (int i = 0; i < entries.size(); i++)
			{
				if (entries.get(i) == mention)
				{
					found = i;
					break;
				}
			}
			if (found < 0)
			{
				return false;
			}
			entries.remove(found);
		}
		changed();
		return true;
	}

	/** Empties the ledger and tells every listener, whether or not it held anything. */
	void clear()
	{
		synchronized (this)
		{
			entries.clear();
		}
		changed();
	}

	/** Sets the cap (below 1 reads as 1), drops the oldest beyond it, and tells only when something went. */
	void resize(int cap)
	{
		boolean dropped = false;
		synchronized (this)
		{
			this.cap = Math.max(1, cap);
			while (entries.size() > this.cap)
			{
				entries.remove(entries.size() - 1);
				dropped = true;
			}
		}
		if (dropped)
		{
			changed();
		}
	}

	/** Has {@code listener} told after every change, on the changing thread. */
	synchronized void listen(Runnable listener)
	{
		listeners.add(listener);
	}

	/** Tells every listener, on the caller's thread, with no lock held. */
	private void changed()
	{
		final List<Runnable> told;
		synchronized (this)
		{
			told = new ArrayList<>(listeners);
		}
		for (final Runnable listener : told)
		{
			listener.run();
		}
	}
}

package com.chatmentions;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

/**
 * The sidebar button's icon, 16 x 16 px: the 2hBuilds coin top-left ({@link CoinGlyph}) and the plugin's own
 * picture clear of the coin, bottom-right. The picture is two stacked mention cards: the back one in soft grey,
 * the front one in white with a line lit in the mention blue, the colour the panel gives a keyword, and a clear
 * ring between the two so they read apart. It is sheet 1's number 4 of {@code docs/pictures}
 * ({@code chat_mentions_picture.py}, {@code icon_d}), picked 2026-10-28. Drawn in code, so it needs no image file.
 */
public final class NavIcon
{
	/** The sidebar icon size. */
	public static final int SIZE = 16;

	/** The picture's colours: the back card's soft grey, the front card's white, the mention blue. */
	private static final int SOFT = new Color(170, 170, 170).getRGB();
	private static final int WHITE = new Color(240, 240, 240).getRGB();
	private static final int BLUE = new Color(59, 130, 246).getRGB();

	/**
	 * The picture, one character a pixel, sixteen rows of sixteen: S the back card's soft grey, W the front card's
	 * white, B the mention blue, '.' nothing (the sidebar's own grey shows). The same map as the picture file's.
	 */
	private static final String[] PICTURE = {
		"................",
		"................",
		"................",
		"................",
		"................",
		"................",
		"................",
		"..........SSSSSS",
		"..........S....S",
		"...............S",
		".......WWWWWWW.S",
		".......W.....W.S",
		".......W.BBB.W..",
		".......W.....W..",
		".......WWWWWWW..",
		"................",
	};

	private NavIcon()
	{
	}

	/** A new 16 x 16 ARGB image of the icon. */
	public static BufferedImage create()
	{
		final BufferedImage img = new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			CoinGlyph.paint(g);
		}
		finally
		{
			g.dispose();
		}
		for (int y = 0; y < SIZE; y++)
		{
			for (int x = 0; x < SIZE; x++)
			{
				final int argb = colour(PICTURE[y].charAt(x));
				if (argb != 0)
				{
					img.setRGB(x, y, argb);
				}
			}
		}
		return img;
	}

	/** The opaque ARGB value a picture character stands for, or 0 for nothing. */
	private static int colour(char c)
	{
		switch (c)
		{
			case 'S':
				return SOFT;
			case 'W':
				return WHITE;
			case 'B':
				return BLUE;
			default:
				return 0;
		}
	}
}

