package com.chatmentions;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/**
 * A chat line as plain text: the game's string variables filled in, the tags gone, the no-break space a plain space,
 * the ends trimmed. Pure; the only client code it touches is {@link Text#removeTags}.
 */
final class PlainText
{
	/** The task prefix {@code CA_ID:<digits>|} with the whitespace around it, at the start of a text. */
	private static final Pattern LEAD = Pattern.compile("^\\s*(?:CA_ID:\\d+\\|)?\\s*");
	/** Any tag. */
	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	/**
	 * A string variable tag: {@code <str_NAME=VALUE>} defines one (group 3 is the value, up to the first "&gt;") and
	 * {@code <str_NAME>} refers to one (group 2 is null).
	 */
	private static final Pattern VARIABLE = Pattern.compile("<str_([A-Za-z0-9_]+)(=([^>]*))?>");

	private PlainText()
	{
	}

	/**
	 * The raw message with the game's string variables resolved: each definition tag is removed and remembered (a later
	 * one of the same NAME replaces the earlier), each reference tag becomes the value remembered for its NAME, or
	 * nothing when it was never defined. Every other tag and character stays; null gives an empty text.
	 */
	static String expand(String raw)
	{
		if (raw == null)
		{
			return "";
		}
		final Map<String, String> values = new HashMap<>();
		final StringBuilder out = new StringBuilder(raw.length());
		final Matcher tags = TAG.matcher(raw);
		int from = 0;
		while (tags.find())
		{
			out.append(raw, from, tags.start());
			from = tags.end();
			final Matcher variable = VARIABLE.matcher(tags.group());
			if (!variable.matches())
			{
				out.append(tags.group());
			}
			else if (variable.group(2) != null)
			{
				values.put(variable.group(1), variable.group(3));
			}
			else
			{
				out.append(values.getOrDefault(variable.group(1), ""));
			}
		}
		return out.append(raw, from, raw.length()).toString();
	}

	/**
	 * The message expanded, without its tags, with every U+00A0 written as a plain space, without a leading
	 * {@code CA_ID:<digits>|} and the whitespace around it, and without trailing whitespace; an empty text for null.
	 *
	 * <p>Choice: the prefix is taken off only when it stands first once the tags are gone, which is where the game puts
	 * it. Each no-break space is one character, so the length and every offset stay true.
	 */
	static String plain(String raw)
	{
		if (raw == null)
		{
			return "";
		}
		final String text = Text.removeTags(expand(raw)).replace('\u00a0', ' ');
		final Matcher lead = LEAD.matcher(text);
		final int from = lead.find() ? lead.end() : 0;
		int to = text.length();
		while (to > from && Character.isWhitespace(text.charAt(to - 1)))
		{
			to--;
		}
		return text.substring(from, to);
	}

	/**
	 * A sender's name as the game sends it (a rank icon tag in front, a no-break space inside): {@link #plain} with
	 * every run of spaces collapsed to one; an empty text for null.
	 */
	static String name(String raw)
	{
		return plain(raw).replaceAll(" +", " ");
	}
}

package com.chatmentions;

import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.swing.Icon;
import javax.swing.ImageIcon;
import net.runelite.api.IndexedSprite;

/**
 * The icons the game put before senders' names (a clan rank, a player's crown), as Swing icons at the sprite's own size.
 * The client thread captures an icon the first time a line carries its number; the event thread reads them. Every method
 * is synchronized on the object, since the two threads meet here.
 *
 * <p>Choice: an icon is drawn once and kept; the game's sprite for a number does not change while the client runs.
 */
final class RankIcons
{
	/** The tag the game puts in front of a name: {@code <img=N>}, N one to nine digits. */
	private static final Pattern TAG = Pattern.compile("<img=(\\d{1,9})>");

	private final Map<Integer, Icon> icons = new HashMap<>();

	/** The number in the first {@code <img=N>} tag of a raw name; -1 for none, a null name or a longer number. */
	static int indexIn(String rawName)
	{
		if (rawName == null)
		{
			return -1;
		}
		final Matcher tag = TAG.matcher(rawName);
		return tag.find() ? Integer.parseInt(tag.group(1)) : -1;
	}

	/**
	 * Draws the sprite at {@code index} of the game's mod icons, unless it was drawn already or there is none. Each
	 * pixel's palette entry goes at its offset in an image of the sprite's original size (its own size when an original
	 * is 0 or less); palette entry 0 is see-through. Called on the client thread.
	 */
	synchronized void capture(int index, IndexedSprite[] modIcons)
	{
		if (index < 0 || modIcons == null || index >= modIcons.length || modIcons[index] == null
			|| icons.containsKey(index))
		{
			return;
		}
		final IndexedSprite sprite = modIcons[index];
		final int width = sprite.getOriginalWidth() > 0 && sprite.getOriginalHeight() > 0
			? sprite.getOriginalWidth() : sprite.getWidth();
		final int height = sprite.getOriginalWidth() > 0 && sprite.getOriginalHeight() > 0
			? sprite.getOriginalHeight() : sprite.getHeight();
		if (width <= 0 || height <= 0)
		{
			return;
		}
		final BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		final byte[] pixels = sprite.getPixels();
		final int[] palette = sprite.getPalette();
		for (int y = 0; y < sprite.getHeight(); y++)
		{
			for (int x = 0; x < sprite.getWidth(); x++)
			{
				final int at = y * sprite.getWidth() + x;
				if (pixels == null || palette == null || at >= pixels.length)
				{
					continue;
				}
				final int entry = pixels[at] & 0xff;
				final int px = sprite.getOffsetX() + x;
				final int py = sprite.getOffsetY() + y;
				if (entry == 0 || entry >= palette.length || px < 0 || py < 0 || px >= width || py >= height)
				{
					continue;
				}
				image.setRGB(px, py, 0xFF000000 | palette[entry]);
			}
		}
		icons.put(index, new ImageIcon(image));
	}

	/** The icon captured for {@code index}, or null when none was. Called on the event thread. */
	synchronized Icon icon(int index)
	{
		return icons.get(index);
	}
}

package com.chatmentions;

import java.awt.Dimension;
import java.awt.Point;
import java.awt.Rectangle;

/**
 * Where a window goes on the screen, worked out apart from any window so that it can be tested: nothing here touches
 * the screen itself, the caller hands over the room it has.
 */
final class ScreenPlace
{
	/** How far left of and above the point a window's top-left corner sits, so that the point rests on its top edge. */
	static final int NUDGE = 10;

	private ScreenPlace()
	{
	}

	/**
	 * The top-left corner for a window of {@code size} that opens at {@code at}: {@link #NUDGE} px left of and above
	 * it, held inside {@code screen} (at its left and top edges when the window is bigger than the room).
	 *
	 * @param at the point on the screen the window opens at, the mouse at a press
	 * @param size the window's size
	 * @param screen the usable area of the screen the point is on
	 */
	static Point near(Point at, Dimension size, Rectangle screen)
	{
		final int x = at.x - NUDGE;
		final int y = at.y - NUDGE;
		return new Point(
			Math.max(screen.x, Math.min(x, screen.x + screen.width - size.width)),
			Math.max(screen.y, Math.min(y, screen.y + screen.height - size.height)));
	}
}

