package com.chatmentions;

import net.runelite.api.ChatMessageType;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/** {@link Chat}: which chat a kind of line belongs to, which kinds a player typed, and the labels. */
public class ChatTest
{
	private static void kind(ChatMessageType type, Chat expected)
	{
		assertEquals("the chat of " + type, expected, Chat.of(type));
	}

	private static void kinds(Chat expected, ChatMessageType... types)
	{
		for (final ChatMessageType type : types)
		{
			kind(type, expected);
		}
	}

	@Test
	public void everyKeptKindMapsToItsChat()
	{
		kinds(Chat.PUBLIC, ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT, ChatMessageType.AUTOTYPER,
			ChatMessageType.MODAUTOTYPER);
		kinds(Chat.PRIVATE, ChatMessageType.PRIVATECHAT, ChatMessageType.PRIVATECHATOUT, ChatMessageType.MODPRIVATECHAT);
		kinds(Chat.CHANNEL, ChatMessageType.FRIENDSCHAT, ChatMessageType.FRIENDSCHATNOTIFICATION);
		kinds(Chat.CLAN, ChatMessageType.CLAN_CHAT, ChatMessageType.CLAN_MESSAGE, ChatMessageType.CLAN_GUEST_CHAT,
			ChatMessageType.CLAN_GUEST_MESSAGE, ChatMessageType.CLAN_GIM_CHAT, ChatMessageType.CLAN_GIM_MESSAGE);
		kinds(Chat.GAME, ChatMessageType.GAMEMESSAGE, ChatMessageType.ENGINE, ChatMessageType.BROADCAST,
			ChatMessageType.WELCOME, ChatMessageType.LOGINLOGOUTNOTIFICATION, ChatMessageType.FRIENDNOTIFICATION,
			ChatMessageType.IGNORENOTIFICATION, ChatMessageType.ITEM_EXAMINE, ChatMessageType.NPC_EXAMINE,
			ChatMessageType.OBJECT_EXAMINE, ChatMessageType.SPAM, ChatMessageType.PLAYERRELATED,
			ChatMessageType.TENSECTIMEOUT, ChatMessageType.LEVELUPMESSAGE, ChatMessageType.CONSOLE,
			ChatMessageType.DIDYOUKNOW, ChatMessageType.CLAN_CREATION_INVITATION, ChatMessageType.CLAN_GIM_FORM_GROUP,
			ChatMessageType.CLAN_GIM_GROUP_WITH);
		kinds(Chat.TRADE, ChatMessageType.TRADEREQ, ChatMessageType.TRADE, ChatMessageType.TRADE_SENT,
			ChatMessageType.CHALREQ_TRADE, ChatMessageType.CHALREQ_FRIENDSCHAT, ChatMessageType.CHALREQ_CLANCHAT);
		kinds(null, ChatMessageType.DIALOG, ChatMessageType.MESBOX, ChatMessageType.NPC_SAY,
			ChatMessageType.SNAPSHOTFEEDBACK, ChatMessageType.UNKNOWN);
		assertNull("null is no chat", Chat.of(null));
		for (final ChatMessageType type : ChatMessageType.values())
		{
			assertTrue(type + " is never All", Chat.of(type) != Chat.ALL);
		}
	}

	@Test
	public void spokenIsTrueOnlyForAPlayersOwnWords()
	{
		final ChatMessageType[] typed = {ChatMessageType.CLAN_CHAT, ChatMessageType.CLAN_GUEST_CHAT,
			ChatMessageType.CLAN_GIM_CHAT, ChatMessageType.FRIENDSCHAT, ChatMessageType.PRIVATECHAT,
			ChatMessageType.MODPRIVATECHAT, ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT,
			ChatMessageType.AUTOTYPER, ChatMessageType.MODAUTOTYPER};
		for (final ChatMessageType type : typed)
		{
			assertTrue(type + " is a line a player typed", Chat.spoken(type));
		}
		final ChatMessageType[] broadcast = {ChatMessageType.CLAN_MESSAGE, ChatMessageType.CLAN_GUEST_MESSAGE,
			ChatMessageType.CLAN_GIM_MESSAGE, ChatMessageType.FRIENDSCHATNOTIFICATION, ChatMessageType.PRIVATECHATOUT,
			ChatMessageType.GAMEMESSAGE, ChatMessageType.TRADEREQ};
		for (final ChatMessageType type : broadcast)
		{
			assertFalse(type + " is not a line a player typed", Chat.spoken(type));
		}
		assertFalse("null is not spoken", Chat.spoken(null));
	}

	@Test
	public void theLabelsAreTheShortWords()
	{
		assertArrayEquals("the seven tabs in the game's order", new Chat[]{Chat.ALL, Chat.GAME, Chat.PUBLIC, Chat.PRIVATE,
			Chat.CHANNEL, Chat.CLAN, Chat.TRADE}, Chat.values());
		assertEquals("All label", "All", Chat.ALL.label());
		assertEquals("Game label", "Game", Chat.GAME.label());
		assertEquals("Public label", "Public", Chat.PUBLIC.label());
		assertEquals("Private label", "Private", Chat.PRIVATE.label());
		assertEquals("Channel label", "Channel", Chat.CHANNEL.label());
		assertEquals("Clan label", "Clan", Chat.CLAN.label());
		assertEquals("Trade label", "Trade", Chat.TRADE.label());
	}
}

package com.chatmentions;

import java.awt.Color;
import java.awt.image.BufferedImage;
import javax.swing.ImageIcon;
import net.runelite.client.ui.ColorScheme;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/** {@link GearGlyph}, in memory: its size, its transparent corners and hole, and the colour of its ring. */
public class GearGlyphTest
{
	private static final Color ORANGE = new Color(220, 138, 0);

	private static BufferedImage image(ImageIcon icon)
	{
		return (BufferedImage) icon.getImage();
	}

	@Test
	public void theIconIsAsBigAsAskedAndNoSmallerThanTheMinimum()
	{
		final ImageIcon twelve = GearGlyph.icon(12, ORANGE);
		assertEquals(12, twelve.getIconWidth());
		assertEquals(12, twelve.getIconHeight());
		assertEquals(GearGlyph.MIN_SIZE, GearGlyph.icon(3, ORANGE).getIconWidth());
	}

	@Test
	public void theFourCornersAndTheHoleAreTransparent()
	{
		final BufferedImage img = image(GearGlyph.icon(12, ORANGE));
		assertEquals(0, img.getRGB(0, 0) >>> 24);
		assertEquals(0, img.getRGB(11, 0) >>> 24);
		assertEquals(0, img.getRGB(0, 11) >>> 24);
		assertEquals(0, img.getRGB(11, 11) >>> 24);
		assertEquals(0, img.getRGB(5, 5) >>> 24);
		assertEquals(0, img.getRGB(6, 6) >>> 24);
	}

	@Test
	public void theRingIsSolidInTheGivenColour()
	{
		// (8, 7) sits on the ring between two teeth: well inside the metal, so fully opaque.
		assertEquals(0xFF000000 | ORANGE.getRGB(), image(GearGlyph.icon(12, ORANGE)).getRGB(8, 7));
	}

	@Test
	public void noColourMeansTheSidebarsGrey()
	{
		assertEquals(0xFF000000 | ColorScheme.LIGHT_GRAY_COLOR.getRGB(), image(GearGlyph.icon(12, null)).getRGB(8, 7));
		assertEquals(new Color(165, 165, 165), ColorScheme.LIGHT_GRAY_COLOR);
	}
}

package com.chatmentions;

import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/** {@link Keywords}: the cleaned word list and the finder. */
public class KeywordsTest
{
	/** Checks the hits against the expected {@code {start, end}} pairs, given flat. */
	private static void hits(String message, List<int[]> found, int... flat)
	{
		assertEquals(message + ": how many hits", flat.length / 2, found.size());
		for (int i = 0; i < found.size(); i++)
		{
			assertArrayEquals(message + ": hit " + i, new int[]{flat[2 * i], flat[2 * i + 1]},
				Arrays.copyOf(found.get(i), 2));
		}
	}

	@Test
	public void theSettingSplitsOnCommasAndIsCleaned()
	{
		final Keywords keywords = Keywords.of(" 2h, Sanka ,,klar\u00a0x, sanka ", false, "Me");
		assertEquals("the name first, then cleaned, deduplicated, in order and case",
			Arrays.asList("Me", "2h", "Sanka", "klar x"), keywords.words());
		try
		{
			keywords.words().add("no");
			fail("the words cannot be added to");
		}
		catch (UnsupportedOperationException expected)
		{
			assertTrue("unmodifiable", true);
		}
	}

	@Test
	public void theNameIsAlwaysTheFirstWord()
	{
		assertEquals("empty setting", Arrays.asList("Sanka"), Keywords.of("", false, "Sanka").words());
		assertEquals("only separators", Arrays.asList("Sanka"), Keywords.of(" , ", false, "Sanka").words());
		assertEquals("the name leads and is not repeated", Arrays.asList("Sanka", "bond", "split"),
			Keywords.of("bond, SANKA, split", false, "Sanka").words());
		assertEquals("no name", Arrays.asList("bond"), Keywords.of("bond", false, null).words());
		final Keywords none = Keywords.of(null, false, null);
		assertTrue("no setting and no name", none.words().isEmpty());
		assertTrue("no words find nothing", none.find("Sanka").isEmpty());
		assertTrue("a blank name is no word", Keywords.of("", false, "  ").words().isEmpty());
	}

	@Test
	public void aWholeWordHitIgnoresCase()
	{
		final Keywords keywords = Keywords.of("sanka", false, null);
		hits("upper case", keywords.find("SANKA come to ge"), 0, 5);
		hits("at the end", keywords.find("hey Sanka"), 4, 9);
		hits("inside a word", keywords.find("sankas"));
		hits("empty text", keywords.find(""));
		hits("null text", keywords.find(null));
	}

	@Test
	public void lettersAndDigitsBreakAWordPunctuationDoesNot()
	{
		final Keywords keywords = Keywords.of("2h", false, null);
		hits("letters after", keywords.find("2hbuilds"));
		hits("letter before", keywords.find("x2h"));
		hits("digit after", keywords.find("2h5"));
		hits("brackets", keywords.find("(2h)"), 1, 3);
		hits("comma", keywords.find("2h,"), 0, 2);
		hits("full stop", keywords.find("the 2h."), 4, 6);
		hits("no-break space", keywords.find("2h\u00a0builds"), 0, 2);
	}

	@Test
	public void partialWordsHitInsideWords()
	{
		hits("inside words", Keywords.of("2h", true, null).find("2hbuilds and x2h"), 0, 2, 14, 16);
	}

	@Test
	public void hitsAreSortedAndOverlapsMerge()
	{
		hits("sorted", Keywords.of("klar,2h", false, null).find("2h and klar"), 0, 2, 7, 11);
		hits("contained", Keywords.of("sank,sanka", true, null).find("sanka"), 0, 5);
		hits("overlapping", Keywords.of("ab,bc", true, null).find("abc"), 0, 3);
		hits("touching stays apart", Keywords.of("2h,hi", true, null).find("2hhi"), 0, 2, 2, 4);
	}

	@Test
	public void theSameWordTwiceInALineGivesTwoHits()
	{
		hits("twice", Keywords.of("2h", false, null).find("2h here, 2h there"), 0, 2, 9, 11);
	}

	@Test
	public void aHitNamesItsWord()
	{
		final List<int[]> found = Keywords.of("bond, yama", false, "Sanka").find("yama and bond and sanka");
		assertEquals(3, found.size());
		assertArrayEquals(new int[]{0, 4, 2}, found.get(0));
		assertArrayEquals(new int[]{9, 13, 1}, found.get(1));
		assertArrayEquals(new int[]{18, 23, 0}, found.get(2));

		final List<int[]> first = Keywords.of("ab, bc", true, null).find("abc");
		assertEquals(1, first.size());
		assertArrayEquals(new int[]{0, 3, 0}, first.get(0));
		final List<int[]> second = Keywords.of("bc, ab", true, null).find("abc");
		assertEquals(1, second.size());
		assertArrayEquals(new int[]{0, 3, 0}, second.get(0));
	}
}

package com.chatmentions;

import java.util.List;
import net.runelite.api.ChatMessageType;
import org.junit.Test;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** {@link MentionFeed}: the lines kept, the cards made, the watched set and the sizes. */
public class MentionFeedTest
{
	private static void assertOthersEmpty(MentionFeed feed, Chat except)
	{
		for (final Chat chat : Chat.values())
		{
			if (chat != except && chat != Chat.ALL)
			{
				assertEquals(chat + " is empty", 0, feed.buffer(chat).lines().size());
			}
		}
	}

	@Test
	public void aSpokenLineWithAKeywordIsKeptAndMakesACard()
	{
		final MentionFeed feed = new MentionFeed(100, 10);
		feed.keywords("2h", false);
		feed.playerName("Sanka");
		assertTrue(feed.line(ChatMessageType.CLAN_CHAT, "<img=41>Klar", "<col=0000ff>gz 2h!</col>", 5000));

		final List<ChatLine> lines = feed.buffer(Chat.CLAN).lines();
		assertEquals(1, lines.size());
		assertEquals(1, lines.get(0).seq());
		assertEquals(5000, lines.get(0).at());
		assertEquals("Klar", lines.get(0).who());
		assertEquals("gz 2h!", lines.get(0).text());
		assertTrue(lines.get(0).spoken());

		final List<Mention> cards = feed.ledger().mentions();
		assertEquals(1, cards.size());
		assertEquals(Chat.CLAN, cards.get(0).chat());
		assertEquals(1, cards.get(0).seq());
		assertEquals(5000, cards.get(0).at());
		assertEquals("Klar", cards.get(0).who());
		assertEquals("gz 2h!", cards.get(0).text());
		assertEquals(1, cards.get(0).spans().size());
		assertArrayEquals(new int[]{3, 5}, java.util.Arrays.copyOf(cards.get(0).spans().get(0), 2));
		assertOthersEmpty(feed, Chat.CLAN);
	}

	@Test
	public void anUnwatchedChatKeepsNothing()
	{
		final MentionFeed feed = new MentionFeed(100, 10);
		feed.keywords("2h", false);
		feed.watch(Chat.PUBLIC, false);
		assertFalse(feed.line(ChatMessageType.PUBLICCHAT, "Klar", "2h", 1));
		assertEquals(0, feed.buffer(Chat.PUBLIC).lines().size());
		assertEquals(0, feed.ledger().mentions().size());

		feed.watch(Chat.PUBLIC, true);
		assertTrue(feed.line(ChatMessageType.PUBLICCHAT, "Klar", "2h", 1));
		assertEquals(1, feed.buffer(Chat.PUBLIC).lines().size());
	}

	@Test
	public void theGamesBroadcastIsKeptButMakesNoCard()
	{
		final MentionFeed feed = new MentionFeed(100, 10);
		feed.keywords("2h", false);
		assertFalse(feed.line(ChatMessageType.CLAN_MESSAGE, "", "2h has completed a quest", 1));
		final List<ChatLine> lines = feed.buffer(Chat.CLAN).lines();
		assertEquals(1, lines.size());
		assertEquals("", lines.get(0).who());
		assertFalse(lines.get(0).spoken());
		assertEquals(0, feed.ledger().mentions().size());
	}

	@Test
	public void thePlayersOwnLineMakesNoCard()
	{
		final MentionFeed feed = new MentionFeed(100, 10);
		feed.keywords("2h", false);
		feed.playerName("<img=2>Sanka");
		assertFalse(feed.line(ChatMessageType.CLAN_CHAT, "SANKA", "2h here", 1));
		assertEquals(1, feed.buffer(Chat.CLAN).lines().size());
		assertTrue(feed.line(ChatMessageType.CLAN_CHAT, "Sankaa", "2h here", 2));
	}

	@Test
	public void thePlayersNameIsAlwaysAKeyword()
	{
		final MentionFeed feed = new MentionFeed(100, 10);
		feed.keywords("", false);
		assertFalse(feed.line(ChatMessageType.CLAN_CHAT, "Klar", "gz sanka", 1));

		feed.playerName("Sanka");
		assertTrue(feed.line(ChatMessageType.CLAN_CHAT, "Klar", "gz Sanka!", 2));
		final Mention card = feed.ledger().mentions().get(0);
		assertEquals(1, card.spans().size());
		assertArrayEquals(new int[]{3, 8}, java.util.Arrays.copyOf(card.spans().get(0), 2));

		feed.keywords("2h", false);
		assertTrue("the name is still a keyword", feed.line(ChatMessageType.CLAN_CHAT, "Klar", "gz sanka", 3));
		assertTrue(feed.line(ChatMessageType.CLAN_CHAT, "Klar", "2h", 4));
	}

	@Test
	public void theSendersIconIndexIsKept()
	{
		final MentionFeed feed = new MentionFeed(100, 10);
		feed.keywords("2h", false);
		feed.playerName("<img=2>Sanka");
		assertEquals("Sanka", feed.playerName());
		assertTrue(feed.line(ChatMessageType.CLAN_CHAT, "<img=41>Klar", "2h here", 1));
		final ChatLine first = feed.buffer(Chat.CLAN).lines().get(0);
		assertEquals("Klar", first.who());
		assertEquals(41, first.icon());
		assertEquals(Chat.CLAN, first.chat());
		final ChatLine inAll = feed.buffer(Chat.ALL).lines().get(0);
		assertEquals(Chat.CLAN, inAll.chat());
		assertEquals(41, inAll.icon());
		assertEquals(41, feed.ledger().mentions().get(0).icon());
		assertTrue(feed.line(ChatMessageType.CLAN_CHAT, "Klar", "2h again", 2));
		assertEquals(-1, feed.buffer(Chat.CLAN).lines().get(1).icon());
	}

	@Test
	public void privateMessagesInAndOut()
	{
		final MentionFeed feed = new MentionFeed(100, 10);
		feed.keywords("2h", false);
		feed.playerName("Sanka");
		assertTrue(feed.line(ChatMessageType.PRIVATECHAT, "Klar", "2h?", 1));
		assertFalse(feed.line(ChatMessageType.PRIVATECHATOUT, "Klar", "2h yes", 2));
		final List<ChatLine> lines = feed.buffer(Chat.PRIVATE).lines();
		assertEquals(2, lines.size());
		assertEquals("Klar", lines.get(0).who());
		assertTrue(lines.get(0).spoken());
		assertEquals("To Klar", lines.get(1).who());
		assertFalse(lines.get(1).spoken());
		assertEquals(1, feed.ledger().mentions().size());
	}

	@Test
	public void aKindThatIsNoChatAndNullsAreHarmless()
	{
		final MentionFeed feed = new MentionFeed(100, 10);
		feed.keywords("2h", false);
		assertFalse(feed.line(ChatMessageType.DIALOG, "", "2h", 1));
		for (final Chat chat : Chat.values())
		{
			assertEquals(0, feed.buffer(chat).lines().size());
		}
		assertFalse(feed.line(null, null, null, 1));
		assertFalse(feed.line(ChatMessageType.CLAN_CHAT, null, null, 1));
		final List<ChatLine> lines = feed.buffer(Chat.CLAN).lines();
		assertEquals(1, lines.size());
		assertEquals("", lines.get(0).who());
		assertEquals("", lines.get(0).text());
	}

	@Test
	public void theSizesFollowTheSettings()
	{
		final MentionFeed feed = new MentionFeed(3, 2);
		feed.keywords("2h", false);
		feed.playerName("Sanka");
		for (int i = 1; i <= 5; i++)
		{
			feed.line(ChatMessageType.CLAN_CHAT, "Klar", "2h " + i, i);
		}
		final List<ChatLine> lines = feed.buffer(Chat.CLAN).lines();
		assertEquals(3, lines.size());
		assertEquals(3, lines.get(0).seq());
		assertEquals(4, lines.get(1).seq());
		assertEquals(5, lines.get(2).seq());
		final List<Mention> cards = feed.ledger().mentions();
		assertEquals(2, cards.size());
		assertEquals(5, cards.get(0).seq());
		assertEquals(4, cards.get(1).seq());

		feed.linesKept(1);
		assertEquals(1, feed.buffer(Chat.CLAN).lines().size());
		assertEquals(5, feed.buffer(Chat.CLAN).lines().get(0).seq());
		feed.cardsKept(1);
		assertEquals(1, feed.ledger().mentions().size());
		assertEquals(5, feed.ledger().mentions().get(0).seq());

		feed.clear();
		for (final Chat chat : Chat.values())
		{
			assertEquals(0, feed.buffer(chat).lines().size());
		}
		assertEquals(0, feed.ledger().mentions().size());
	}

	@Test
	public void everyChatHasItsOwnBuffer()
	{
