package com.chatmentions;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/** {@link MentionLedger}: the cards, newest first. */
public class MentionLedgerTest
{
	private static Mention mention(long seq)
	{
		return new Mention(Chat.CLAN, seq, 1000L * seq, "who", "text " + seq, Collections.<int[]>emptyList(), -1);
	}

	private static AtomicInteger counter(MentionLedger ledger)
	{
		final AtomicInteger told = new AtomicInteger();
		ledger.listen(told::incrementAndGet);
		return told;
	}

	@Test
	public void newestFirstAndTheOldestGoesPastTheCap()
	{
		final MentionLedger ledger = new MentionLedger(3);
		final AtomicInteger told = counter(ledger);
		for (int i = 1; i <= 4; i++)
		{
			ledger.add(mention(i));
		}
		final List<Mention> held = ledger.mentions();
		assertEquals("three held", 3, held.size());
		assertEquals("newest first", 4, held.get(0).seq());
		assertEquals("then 3", 3, held.get(1).seq());
		assertEquals("then 2", 2, held.get(2).seq());
		assertEquals("told four times", 4, told.get());
	}

	@Test
	public void markReadRemovesThatOneAndOnlyThatOne()
	{
		final MentionLedger ledger = new MentionLedger(5);
		final Mention a = mention(1);
		final Mention b = mention(2);
		final Mention c = mention(3);
		ledger.add(a);
		ledger.add(b);
		ledger.add(c);
		final AtomicInteger told = counter(ledger);

		assertTrue("the middle one is removed", ledger.markRead(b));
		final List<Mention> held = ledger.mentions();
		assertEquals("two left", 2, held.size());
		assertSame("newest first", c, held.get(0));
		assertSame("then the oldest", a, held.get(1));
		assertEquals("told once", 1, told.get());

		final Mention twin = mention(3);
		assertFalse("an equal-looking mention is not held", ledger.markRead(twin));
		assertEquals("nothing changed", 2, ledger.mentions().size());
		assertEquals("nobody told", 1, told.get());
		assertFalse("null is false", ledger.markRead(null));
		assertEquals("null tells nobody", 1, told.get());
	}

	@Test
	public void clearEmptiesAndTellsEvenWhenEmpty()
	{
		final MentionLedger ledger = new MentionLedger(5);
		final AtomicInteger told = counter(ledger);
		ledger.clear();
		assertEquals("told once when empty", 1, told.get());
		ledger.add(mention(1));
		ledger.add(mention(2));
		ledger.clear();
		assertEquals("empty", 0, ledger.mentions().size());
		assertEquals("told again", 4, told.get());
	}

	@Test
	public void resizeDropsTheOldestAndNeverBelowOne()
	{
		final MentionLedger ledger = new MentionLedger(5);
		final AtomicInteger told = counter(ledger);
		for (int i = 1; i <= 5; i++)
		{
			ledger.add(mention(i));
		}
		assertEquals("five adds told", 5, told.get());

		ledger.resize(2);
		assertEquals("two held", 2, ledger.mentions().size());
		assertEquals("newest", 5, ledger.mentions().get(0).seq());
		assertEquals("then 4", 4, ledger.mentions().get(1).seq());
		assertEquals("told for the drop", 6, told.get());

		ledger.resize(0);
		assertEquals("one left", 1, ledger.mentions().size());
		assertEquals("the newest", 5, ledger.mentions().get(0).seq());
		assertEquals("told again", 7, told.get());

		ledger.resize(9);
		assertEquals("nothing dropped", 1, ledger.mentions().size());
		assertEquals("nobody told", 7, told.get());
		for (int i = 6; i <= 15; i++)
		{
			ledger.add(mention(i));
		}
		assertEquals("cap 9", 9, ledger.mentions().size());

		final MentionLedger zero = new MentionLedger(0);
		zero.add(mention(1));
		zero.add(mention(2));
		assertEquals("a cap of 0 reads as 1", 1, zero.mentions().size());
	}

	@Test
	public void aListenerIsToldWithNoLockHeldAndSeesTheNewState()
	{
		final MentionLedger ledger = new MentionLedger(5);
		final List<Integer> sizes = new ArrayList<>();
		final List<Integer> listed = new ArrayList<>();
		ledger.listen(() ->
		{
			sizes.add(ledger.mentions().size());
			listed.add(ledger.mentions().size());
		});
		ledger.add(mention(1));
		assertEquals("told once", 1, sizes.size());
		assertEquals("size seen inside the listener", Integer.valueOf(1), sizes.get(0));
		assertEquals("mentions seen inside the listener", Integer.valueOf(1), listed.get(0));

		ledger.add(null);
		assertEquals("null adds nothing", 1, ledger.mentions().size());
		assertEquals("null tells nobody", 1, sizes.size());

		final List<int[]> source = new ArrayList<>(Arrays.asList(new int[]{0, 2}, new int[]{4, 6}));
		final Mention built = new Mention(Chat.PUBLIC, 1, 1, "w", "t", source, -1);
		source.clear();
		assertEquals("the spans were copied", 2, built.spans().size());
		try
		{
			built.spans().add(new int[]{1, 2});
			fail("the spans cannot be added to");
		}
		catch (UnsupportedOperationException expected)
		{
			assertTrue("unmodifiable", true);
		}
	}
}

package com.chatmentions;

import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * {@link NavIcon}, in memory: the size, the coin exactly as {@link CoinGlyph} draws it, the picture clear of it, and
 * the picture itself pinned: the two stacked cards of sheet 1's number 4, picked 2026-10-28.
 */
public class NavIconTest
{
	/** The coin's centre and the farthest its jittered rim reaches from it, with a pixel of margin. */
	private static final double COIN_CENTRE = 4.5;
	private static final double CLEAR_DISTANCE = 6.0;

	/** The picture's colours, as opaque ARGB: the back card's soft grey, the front card's white, the mention blue. */
	private static final int SOFT = 0xFFAAAAAA;
	private static final int WHITE = 0xFFF0F0F0;
	private static final int BLUE = 0xFF3B82F6;

	/** How many pixels the picture adds to the coin: 20 white, 11 soft grey, 3 blue. */
	private static final int PICTURE_PIXELS = 34;

	private static BufferedImage coinAlone()
	{
		final BufferedImage img = new BufferedImage(NavIcon.SIZE, NavIcon.SIZE, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		try
		{
			CoinGlyph.paint(g);
		}
		finally
		{
			g.dispose();
		}
		return img;
	}

	private static void assertPixel(String what, int expected, BufferedImage icon, int x, int y)
	{
		assertEquals(what + " at " + x + "," + y, expected, icon.getRGB(x, y));
	}

	private static void assertClear(String what, BufferedImage icon, int x, int y)
	{
		assertEquals(what + " at " + x + "," + y + " is clear", 0, icon.getRGB(x, y) >>> 24);
	}

	@Test
	public void theIconIsSixteenBySixteenArgb()
	{
		final BufferedImage icon = NavIcon.create();
		assertEquals(16, icon.getWidth());
		assertEquals(16, icon.getHeight());
		assertEquals(BufferedImage.TYPE_INT_ARGB, icon.getType());
	}

	@Test
	public void theCoinIsDrawnPixelForPixelAsTheCoinGlyphDrawsIt()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int coinPixels = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if ((coin.getRGB(x, y) >>> 24) != 0)
				{
					coinPixels++;
					assertEquals("coin pixel " + x + "," + y, coin.getRGB(x, y), icon.getRGB(x, y));
				}
			}
		}
		assertTrue("the coin drew something", coinPixels > 0);
	}

	@Test
	public void thePictureLiesClearOfTheCoinsCircle()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int pictureOnly = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if (icon.getRGB(x, y) != coin.getRGB(x, y))
				{
					pictureOnly++;
					final double dx = x + 0.5 - COIN_CENTRE;
					final double dy = y + 0.5 - COIN_CENTRE;
					assertTrue("picture pixel " + x + "," + y + " is too near the coin",
						Math.sqrt(dx * dx + dy * dy) >= CLEAR_DISTANCE);
				}
			}
		}
		assertTrue("the picture drew something", pictureOnly > 0);
	}

	@Test
	public void thePictureIsTheTwoStackedCards()
	{
		final BufferedImage icon = NavIcon.create();
		final BufferedImage coin = coinAlone();
		int differing = 0;
		for (int y = 0; y < NavIcon.SIZE; y++)
		{
			for (int x = 0; x < NavIcon.SIZE; x++)
			{
				if (icon.getRGB(x, y) != coin.getRGB(x, y))
				{
					differing++;
				}
			}
		}
		assertEquals("the picture's pixels", PICTURE_PIXELS, differing);

		// Rows 0 to 6 and row 15 hold the coin alone: the picture starts at row 7 and keeps a row of air below.
		for (int x = 0; x < NavIcon.SIZE; x++)
		{
			for (int y = 0; y <= 6; y++)
			{
				assertEquals("row " + y + " is the coin alone at " + x, coin.getRGB(x, y), icon.getRGB(x, y));
			}
			assertClear("row 15", icon, x, 15);
		}

		// The back card: its top edge, its right edge down to row 11, its two pixels of left edge, the hollow inside.
		assertPixel("soft grey", SOFT, icon, 10, 7);
		assertPixel("soft grey", SOFT, icon, 15, 7);
		assertPixel("soft grey", SOFT, icon, 10, 8);
		assertPixel("soft grey", SOFT, icon, 15, 11);
		assertClear("the back card's hollow", icon, 12, 8);
		// The clear ring between the cards: the back card's left edge and bottom edge cut away.
		assertClear("the ring", icon, 10, 9);
		assertClear("the ring", icon, 14, 10);
		assertClear("the ring", icon, 14, 11);
		assertClear("the ring", icon, 15, 12);
		// The front card: its four corners, its hollow, and the blue line inside.
		assertPixel("white", WHITE, icon, 7, 10);
		assertPixel("white", WHITE, icon, 13, 10);
		assertPixel("white", WHITE, icon, 7, 14);
		assertPixel("white", WHITE, icon, 13, 14);
		assertClear("the front card's hollow", icon, 8, 11);
		assertClear("the front card's hollow", icon, 12, 13);
		assertClear("the air before the line", icon, 8, 12);
		assertPixel("blue", BLUE, icon, 9, 12);
		assertPixel("blue", BLUE, icon, 10, 12);
		assertPixel("blue", BLUE, icon, 11, 12);
		assertClear("the air after the line", icon, 12, 12);
	}
}

package com.chatmentions;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

/** {@link PlainText}: a chat line and a sender's name as plain text. */
public class PlainTextTest
{
	@Test
	public void tagsIconsAndTheNoBreakSpaceGoAndTheEndsAreTrimmed()
	{
		assertEquals("tags and icon go, the end is trimmed", "Klar: gz 2h!",
			PlainText.plain("<col=0000a0><img=22>Klar: gz 2h!</col> "));
		assertEquals("the no-break space is a plain space", "self ctrl: hi", PlainText.plain("self\u00a0ctrl: hi"));
